impl Readers {
    /// The same readers as the folder it is in (`inherit`). Refused on the root folder, which has no parent.
    pub fn inherit() -> Self {
        Readers {
            kind: ReadersKind::from("inherit"),
            ..Default::default()
        }
    }

    /// Anyone who can reach the knowledge base, signed in or not: guests and anonymous visitors included (`public`).
    pub fn public() -> Self {
        Readers {
            kind: ReadersKind::from("public"),
            ..Default::default()
        }
    }

    /// Anyone signed in who may read the knowledge base (`everyone`).
    pub fn everyone() -> Self {
        Readers {
            kind: ReadersKind::from("everyone"),
            ..Default::default()
        }
    }

    /// Only these roles and people (`specific`).
    pub fn specific(roles: impl IntoIterator<Item = impl Into<String>>, people: impl IntoIterator<Item = impl Into<String>>) -> Self {
        Readers {
            kind: ReadersKind::from("specific"),
            roles: Some(roles.into_iter().map(Into::into).collect()),
            people: Some(people.into_iter().map(Into::into).collect()),
            ..Default::default()
        }
    }

    /// Only these roles.
    pub fn roles(roles: impl IntoIterator<Item = impl Into<String>>) -> Self {
        Readers {
            kind: ReadersKind::from("specific"),
            roles: Some(roles.into_iter().map(Into::into).collect()),
            ..Default::default()
        }
    }

    /// Only these people.
    pub fn people(people: impl IntoIterator<Item = impl Into<String>>) -> Self {
        Readers {
            kind: ReadersKind::from("specific"),
            people: Some(people.into_iter().map(Into::into).collect()),
            ..Default::default()
        }
    }
}

/// `"inherit"`, `"public"` or `"everyone"`: `.readers("inherit")`. Any other value is sent as the kind it names.
impl From<&str> for Readers {
    fn from(kind: &str) -> Self {
        Readers {
            kind: ReadersKind::from(kind),
            ..Default::default()
        }
    }
}

/// A thing's processing, as a wait's progress callback and a watch event's `processing()` give it: a document's
/// [`DocumentProcessing`] (its stage, percentage and time left), or the running [`Job`] of a batch, a folder or a
/// knowledge base.
#[derive(Debug, Clone, PartialEq)]
pub enum Processing {
    Document(Box<DocumentProcessing>),
    Job(Box<Job>),
}

impl Processing {
    /// How far it has got, from 0 to 100; it never moves back.
    pub fn percent(&self) -> Option<i32> {
        match self {
            Processing::Document(p) => Some(p.percent),
            Processing::Job(j) => j.percent,
        }
    }

    /// How long is left, once it has run long enough to say.
    pub fn eta(&self) -> Option<&Eta> {
        match self {
            Processing::Document(p) => p.eta.as_ref(),
            Processing::Job(j) => j.eta.as_ref(),
        }
    }

    /// A document's stage (`pages`, `passages`, …); a job has none.
    pub fn stage(&self) -> Option<&ProcessingStep> {
        match self {
            Processing::Document(p) => p.stage.as_ref(),
            Processing::Job(_) => None,
        }
    }

    /// For a wait's progress callback: a watch event as JSON, read for the document `id`'s processing (`thing`
    /// "document") or a running job (`thing` "job").
    pub(crate) fn observer(f: rt::watch::ProgressFn<Processing>, thing: &'static str, id: String) -> rt::watch::Observer {
        Box::new(move |v: &serde_json::Value| {
            let name = v["type"].as_str().unwrap_or_default().to_owned();
            let mut data = v.clone();
            if let serde_json::Value::Object(o) = &mut data {
                o.remove("type");
            }
            let Ok(bytes) = serde_json::to_vec(&data) else { return };
            let Ok(rt::Decoded::Event(ev)) = decode_knowledge_base_event(&name, None, &bytes) else {
                return;
            };
            let p = if thing == "document" {
                ev.processing_of(&id).filter(|p| matches!(p, Processing::Document(_)))
            } else {
                ev.processing().filter(|p| matches!(p, Processing::Job(_)))
            };
            if let Some(p) = p {
                f(&p);
            }
        })
    }
}

impl KnowledgeBaseEvent {
    /// The processing this event carries, for a scope's watch: the watched document's, from a snapshot or a
    /// `document.progress`; or the running job, from the snapshot of a batch, a folder or a knowledge base, or a
    /// `job.progress`. `None` when it carries none.
    pub fn processing(&self) -> Option<Processing> {
        match self {
            KnowledgeBaseEvent::Snapshot(s) => match &s.document {
                Some(d) => s
                    .progress
                    .iter()
                    .find(|p| p.document_id == d.id)
                    .map(|p| Processing::Document(Box::new(p.processing.clone()))),
                None => s.jobs.iter().find(|j| running(j)).map(|j| Processing::Job(Box::new(j.clone()))),
            },
            KnowledgeBaseEvent::DocumentProgress(p) => Some(Processing::Document(Box::new(p.processing.clone()))),
            KnowledgeBaseEvent::JobProgress(j) => Some(Processing::Job(Box::new(j.job.clone()))),
            _ => None,
        }
    }

    /// The processing of one document or job (by its id, or a job by its target's id), for the knowledge base's own
    /// watch, which carries many. `None` when this event carries none for it.
    pub fn processing_of(&self, id: &str) -> Option<Processing> {
        let is = |j: &Job| j.id == id || j.target.as_ref().is_some_and(|t| t.id == id);
        match self {
            KnowledgeBaseEvent::Snapshot(s) => s
                .progress
                .iter()
                .find(|p| p.document_id == id)
                .map(|p| Processing::Document(Box::new(p.processing.clone())))
                .or_else(|| {
                    s.jobs
                        .iter()
                        .find(|j| is(j) && running(j))
                        .map(|j| Processing::Job(Box::new(j.clone())))
                }),
            KnowledgeBaseEvent::DocumentProgress(p) if p.document_id == id => Some(Processing::Document(Box::new(p.processing.clone()))),
            KnowledgeBaseEvent::JobProgress(j) if is(&j.job) => Some(Processing::Job(Box::new(j.job.clone()))),
            _ => None,
        }
    }
}

fn running(j: &Job) -> bool {
    matches!(j.status.as_str(), "queued" | "running")
}
